def flood(g,diag=False):
    H,W=len(g),len(g[0])
    reach=[[False]*W for _ in range(H)]; dq=deque()
    border=[(r,c) for r in (0,H-1) for c in range(W)]+[(r,c) for c in (0,W-1) for r in range(H)]
    for b in border:
        if g[b[0]][b[1]]==0 and not reach[b[0]][b[1]]: reach[b[0]][b[1]]=True; dq.append(b)
    while dq:
        r,c=dq.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                if diag and dr!=0 and dc!=0: continue
                nr,nc=r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and not reach[nr][nc] and g[nr][nc]==0:
                    reach[nr][nc]=True; dq.append((nr,nc))
    return reach
